#!/usr/bin/env python3
"""Deepen the late Chenghua to Hongzhi political and fiscal transition."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "App/Resources/history.json"
NARRATION = ROOT / "App/Resources/narration_manifest.json"


def upsert(items: list[dict], item: dict, key: str = "id") -> None:
    for index, old in enumerate(items):
        if old.get(key) == item[key]:
            items[index] = item
            return
    items.append(item)


def sec(sid: str, title: str, text: str, sources: list[str], events: list[str], people: list[str]) -> dict:
    return {"id": sid, "title": title, "text": text, "kind": "史实与解读", "sources": sources, "events": events, "people": people}


def article(person: str, title: str, dek: str, sections: list[dict]) -> dict:
    sources: list[str] = []
    for section in sections:
        for source in section["sources"]:
            if source not in sources:
                sources.append(source)
    return {"person": person, "title": title, "dek": dek, "sections": sections, "sources": sources}


def association(data: dict, item: dict) -> None:
    for index, old in enumerate(data["associations"]):
        if old["from"] == item["from"] and old["to"] == item["to"]:
            data["associations"][index] = item
            return
    data["associations"].append(item)


def main() -> None:
    data = json.loads(DATA.read_text(encoding="utf-8"))
    for source in [
        {"id": "v141_ms168", "title": "《明史》卷168 · 万安、刘吉、尹直传", "url": "https://zh.wikisource.org/zh-hans/明史/卷168", "note": "清修正史开放转录，用于核对万安入阁、宫廷关系、反西厂及弘治初退职。列传以品评士大夫为主，涉及私生活、密奏和宫中对话的材料不能当作逐字现场记录。"},
        {"id": "v141_ms307", "title": "《明史》卷307 · 李孜省等传", "url": "https://zh.wikisource.org/zh-hans/明史/卷307", "note": "清修正史开放转录，用于核对传奉授官、李孜省密奏、寺院营建及成化末清查。该卷按佞幸分类，数字来自官府名册，刑讯后的罪名和道德判断均须保留审慎。"},
        {"id": "v141_ms77", "title": "《明史》卷77 · 食货志一", "url": "https://zh.wikisource.org/zh-hans/明史/卷77", "note": "清修食货志开放转录，用于核对皇庄出现、弘治年间庄田数量、投献与管庄人员扰民。面积和庄数是奏疏、清册口径，不等于现代精确测绘。"},
        {"id": "v141_daxue_yanyibu", "title": "丘濬《大学衍义补》开放电子本", "url": "https://zh.wikisource.org/zh-hans/大学衍义补", "note": "明代政书开放转录，展示丘濬如何按治国条目编排财政、礼制、边防和用人主张。它是规范性方案，不是弘治政策已经逐条实行的记录。"},
    ]:
        upsert(data["sources"], source)

    people = [
        {"id": "m141_wanan", "name": "万安", "call": "在宫廷关系、票拟与沉默政治之间的成化阁臣", "temple": "—", "era": "成化—弘治", "reign": "1419—1489", "summary": "由翰林入阁，长期居成化内阁首位；既参与反对西厂，也借宫廷与万氏关系维持地位，弘治初在舆论和新政清理中退职。", "parent": None, "sources": ["v141_ms168", "v40m1_ms304", "v2l_ms15"], "kind": "内阁大臣", "note": "字循吉，四川眉州人。传统史书的“万岁阁老”等标签带有强烈道德裁判，评价仍须回到具体票拟、人事与宫廷渠道。", "dynasty": "ming"},
        {"id": "m141_lizisheng", "name": "李孜省", "call": "以方术和密奏进入成化人事网络的近幸", "temple": "—", "era": "成化", "reign": "？—1487", "summary": "从地方吏员、逃亡者转入京师方术圈，经梁芳引入宫廷，以秘密奏事影响授官和案件；弘治即位后被逮捕，死于狱中。", "parent": None, "sources": ["v141_ms307", "v40m1_ms304", "v2l_ms15"], "kind": "密奏近幸", "note": "江西南昌人。官修史将其收入佞幸传；现存叙述混有刑讯供词和追责材料，不能把后来定罪反推为每次奏事均属欺诈。", "dynasty": "ming"},
        {"id": "m141_liangfang", "name": "梁芳", "call": "把宫廷采办、方术与传奉授官连接起来的成化宦官", "temple": "—", "era": "成化—弘治", "reign": "生卒年不详", "summary": "以采办珍玩获得信任，联结万贵妃、李孜省及僧道近幸，推动大量传奉授官；弘治初被谪居、下狱。", "parent": None, "sources": ["v40m1_ms304", "v141_ms307", "v2l_ms15"], "kind": "宫廷采办与近侍", "note": "其个人责任明确，但采办、授官和营造都依赖皇帝批准及外朝合作者，不能用一名宦官替整个权力网络承担责任。", "dynasty": "ming"},
    ]
    rewrites = {
        "m40_liujian": {"call": "从东宫讲官到弘治财政与边防议政核心", "summary": "长期担任讲官，弘治朝入阁并主持政务，以节省宫廷支出、整顿盐政屯田和谨慎用兵回应财政与边警。"},
        "m40_xieqian": {"call": "把节用、核查和基层承受力带入内阁的直臣", "summary": "由讲官入阁，反对以边饷不足为由追加南方赋税，主张先核查禁军、仓场和内府积弊；与刘健、李东阳共同辅政。"},
        "m40_lidongyang": {"call": "以诏稿、实地见闻和文学网络参与弘治政务的阁臣", "summary": "由翰林、东宫讲官入阁，擅长诏敕与奏议；出使途中记录灾荒、差役、织造和商税压力，使地方见闻进入中枢。"},
        "m42_qiujun": {"call": "以《大学衍义补》系统整理国家治理问题的学者阁臣", "summary": "从海南贫寒家庭进入翰林，参与实录、教育和两广方略；晚年献《大学衍义补》并入阁，把财政、用人、礼制与边防编成政策体系。"},
    }
    for person in people:
        upsert(data["people"], person)
    for person in data["people"]:
        if person["id"] in rewrites:
            person.update(rewrites[person["id"]])

    events = [
        {"id": "v141_chuanfeng_network", "year": "1470年代—1487年", "title": "传奉授官绕过常规铨选，形成跨宫廷与外朝的人事网络", "category": "政治", "body": "成化后期，部分任命由宫中直接传旨，不经吏部常规资格审查。李孜省、梁芳及其交往者把文武、僧道和技艺人员送入名册，一次传奉可达数百人。", "impact": "传奉不意味着每名被任者都无能力，问题在于资格、缺额与责任难以公开复核。史载总量来自清查名册，不是现代审计；皇帝授权、近侍传递和外朝执行共同构成制度责任。", "people": ["jianshen", "m141_lizisheng", "m141_liangfang", "m141_wanan"], "sources": ["v141_ms307", "v141_ms168", "v40m1_ms304"], "kind": "人事与密旨"},
        {"id": "v141_palace_procurement", "year": "1470年代—1487年", "title": "珍玩采办沿宫廷需求向地方扩散", "category": "经济", "body": "梁芳以珠宝奇巧获得宫廷信任，其同党常借采办、烧造和进献之名在地方索取财物。内库支出与地方供应相互连接，账目却不都经过同一套财政程序。", "impact": "一件宫廷器物背后可能是商人垫价、州县加派、运输和工匠劳动。把责任只归给“贪宦官”会遮蔽皇帝偏好、承办官署与地方代理人；史料也不足以量化每项采办的实际摊派。", "people": ["jianshen", "m141_liangfang", "m141_lizisheng"], "sources": ["v40m1_ms304", "v141_ms307"], "kind": "宫廷消费"},
        {"id": "v141_yongchang_temple", "year": "1480年代", "title": "大永昌寺营建改变京城居民的房屋与生活", "category": "社会", "body": "僧人继晓等获得近幸后，京城营建大永昌寺，官修史称拆迁数百户并大量动用国库。数字带有批判性列传口径，但居民失去住房和营建成本不能从宫廷故事中消失。", "impact": "问题不在佛教信仰本身，而在以密旨取得土地、劳役和财政资源时缺少补偿与公开核验。弘治初清理僧道封号，也不能把各地普通宗教群体都视为近幸网络。", "people": ["jianshen", "m141_liangfang", "m141_lizisheng"], "sources": ["v141_ms307", "v40m1_ms304"], "kind": "营建与迁居"},
        {"id": "v141_1485_review", "year": "1485年", "title": "朝廷清查传奉官，却在保留与复任之间反复", "category": "政治", "body": "言官要求核查传奉官，名册列出五百余人，初议只留六十七人，许多人随后又借宫廷渠道复任。数字反映官府当时的分类，不代表每人的任职经过已被完整查清。", "impact": "清查若没有持续的任命规则和公开案卷，很容易退化为一次名单政治。它显示成化帝并非从不纠偏，也显示纠偏受制于同一套近侍、人情和密旨渠道。", "people": ["jianshen", "m141_lizisheng", "m141_liangfang", "m141_wanan"], "sources": ["v141_ms307", "v141_ms168"], "kind": "人事清查"},
        {"id": "v141_hongzhi_accession_cleanup", "year": "1487年", "title": "弘治即位清退传奉官和近幸，重开常规政务入口", "category": "政治", "body": "孝宗即位后流放或收押李孜省、梁芳等人，清退逾千名传奉官，裁减部分僧道封号，并调整万安、尹直等阁臣。刘健等讲官进入新的议政结构。", "impact": "“千余”是本纪与清查口径，不能当作逐人司法结论。清理减少了特定网络，却没有使宫廷传旨、内库和近侍影响永久消失；李孜省死于刑讯与狱中，也不能因其失势而被合理化。", "people": ["m141_lizisheng", "m141_liangfang", "m141_wanan", "m40_liujian", "jianshen"], "sources": ["v2l_ms15", "v141_ms168", "v141_ms307"], "kind": "政权转换"},
        {"id": "v141_huangzhuang_agents", "year": "1489—1490年", "title": "皇庄与投献土地引出管庄人员扰民问题", "category": "经济", "body": "弘治初，户部尚书李敏报告皇庄及贵戚、宦官庄田扩展，管庄人员侵占民田、财物。朝廷命约束并归还部分土地，又禁止以投献等方式扩大庄田。", "impact": "“皇庄”把宫廷收益直接落到土地和佃户身上。诏令限制不等于侵占立即消失，志书记载的庄数、顷亩也是清册与奏疏口径；理解政策须继续追问地界、租额和基层申诉。", "people": ["m40_liujian", "m40_xieqian", "m40_lidongyang"], "sources": ["v141_ms77", "v2l_ms15"], "kind": "土地与庄田"},
        {"id": "v141_daxue_yanyibu_event", "year": "1487—1491年", "title": "《大学衍义补》由私人著述进入刊行与议政", "category": "文化", "body": "丘濬认为真德秀《大学衍义》对治国平天下条目不足，广泛采集典籍，补写财政、礼制、用人、边防等内容。孝宗命刊行，丘濬入阁后又摘录要点请求讨论。", "impact": "刊行扩大了一套系统治理知识的传播，也不等于书中主张被逐条执行。文本带有十五世纪儒家秩序和作者判断，今天应将其作为政策思想史材料，而非现成答案。", "people": ["m42_qiujun", "m40_liujian"], "sources": ["v40m2_ms181", "v141_daxue_yanyibu"], "kind": "政书与传播"},
        {"id": "v141_weaving_reduction", "year": "1492年", "title": "弘治朝停止一批额外织造并召回监督人员", "category": "经济", "body": "本纪记载朝廷停止额外织造、召还相关内官。织造连接宫廷服用、地方丝料、工匠和运输，减少额外任务有助于降低一部分临时征派。", "impact": "这不是全国织造从此停止，也不能由中央诏令直接推定地方欠料、垫款都已结清。应把它放在宫廷消费与正式岁额的区别中理解。", "people": ["m40_liujian", "m40_xieqian", "m40_lidongyang"], "sources": ["v2l_ms15", "v40m2_ms181"], "kind": "织造与节用"},
        {"id": "v141_border_finance_1501", "year": "1501年", "title": "多线边警让军饷与宫廷支出的矛盾公开化", "category": "军事", "body": "陕西、辽东边警以及湖广、贵州军务并起，军饷不足。刘健等指出光禄供应、织作、斋醮、内库调拨、庄田与营造持续增长，使有限财源难以支持前线。", "impact": "边防不是只看将帅和战斗，还要看税粮、运输与京营训练。奏议主张节用有明确针对性，但它是政策诊断而非财政已经改善的证明，也不能把所有宗教和礼仪开支一概视为无用。", "people": ["m40_liujian", "m40_xieqian", "m40_lidongyang"], "sources": ["v40m2_ms181", "v2l_ms15"], "kind": "军饷与财政"},
        {"id": "v141_lidongyang_drought_journey", "year": "1504年", "title": "李东阳从出使道路把灾荒、差役与流亡带回内阁", "category": "社会", "body": "李东阳赴曲阜祭孔途中见天津、山东旱情，记录挽舟者衣食不足、农民面有菜色，又汇集江南流亡、军伍空虚、织造与商税扰动等消息，上疏要求检查旧奏。", "impact": "道路见闻能纠正只读京城文书的盲点，也仍是一次行程与转述，不代表完整社会调查。其价值在于揭示郡县、庙堂与宫廷之间的信息逐层过滤。", "people": ["m40_lidongyang", "m40_liujian", "m40_xieqian"], "sources": ["v40m2_ms181", "v2l_ms15"], "kind": "灾荒与信息"},
    ]
    for event in events:
        upsert(data["events"], event)

    S168, S307, S304, S15, S181, S77, SDX = "v141_ms168", "v141_ms307", "v40m1_ms304", "v2l_ms15", "v40m2_ms181", "v141_ms77", "v141_daxue_yanyibu"
    articles = [
        article("m141_wanan", "万安：长期居位怎样改变内阁的声音", "他不是一个外号就能概括的“庸相”：反西厂是可核实行动，依靠宫廷关系、压低公开争论也同样需要说明。", [
            sec("v141_wanan_s1", "由翰林进入成化内阁", "万安由进士、翰林官进入内阁，成化五年参与机务，后来长期居首。内阁票拟能整理奏章、起草诏令，却没有脱离皇帝而独立决定人事与财政的权力。理解他的上升，不能只用才学或奸佞解释，还要看到成化帝减少公开召对、信息更多经过近侍和书面票拟的环境。官修传记用强烈品评塑造人物，具体任命和奏议比外号更可靠。", [S168, S15], ["v141_chuanfeng_network"], ["jianshen"]),
            sec("v141_wanan_s2", "宫廷关系成为政治资源", "列传记载万安借同姓关系接近万贵妃家族，并通过近侍维持皇帝信任。这些宫廷细节经过后世整理，不能都当作可逐字验证的密室记录；但他对传奉与近幸少有持续抵制，与人事网络相容。问题不只是私人逢迎，而是当召对减少、任命可由密旨下达时，谁能接近宫门便影响哪些奏章被看见。", [S168, S307], ["v141_chuanfeng_network"], ["jianshen", "m141_liangfang", "m141_lizisheng"]),
            sec("v141_wanan_s3", "反对西厂不能从履历中删去", "汪直势力转衰时，万安参与要求罢西厂。行动发生得较晚，也可能包含权力判断，仍是限制侦缉机构的一次实际选择。历史人物可以在一件事上维护程序，在另一些人事与财政问题上保持沉默；承认这一层，不等于替其长期居位开脱，而是避免用结论倒写全部行为。西厂结束后，传奉和密奏仍继续扩张，也说明撤销单一机构没有修复信息结构。", [S168, S304], ["v140_west_factory_cases", "v141_chuanfeng_network"], ["m40_wangzhi", "jianshen"]),
            sec("v141_wanan_s4", "清查为何只能短暂推进", "1485年朝廷核查传奉官，初步名册裁去大批人员，许多任命后来恢复。作为首辅，万安没有把一次清查转成稳定的资格、缺额和复核制度。首辅不能强迫皇帝，但长期占据票拟位置也不能以无权为由免除责任。五百余人与保留六十七人的数字是当时清册口径；被列名者背景不同，不应被统一写成无能或有罪。", [S168, S307], ["v141_1485_review"], ["m141_lizisheng", "m141_liangfang"]),
            sec("v141_wanan_s5", "弘治更替中的退场", "孝宗即位后，言官集中批评万安，宫中又发现其进献房中术书疏等材料。怀恩撤去其名位，万安最终致仕。相关轶事带有官修史的道德叙事，真正可见的是新君以清退传奉、召用旧讲官和更换阁臣建立政治信号。万安的退场改变了人员，却没有自动让内阁成为独立制衡；之后刘健等仍需依靠召对与皇帝采纳。", [S168, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian", "jianshen"]),
        ]),
        article("m141_lizisheng", "李孜省：密奏、方术与人事通道", "从逃亡吏员到宫廷密奏者，他的经历揭示知识、仪式和人事如何被一条不公开的渠道连接。", [
            sec("v141_lizisheng_s1", "地方吏员如何进入京师方术圈", "李孜省早年是江西地方吏员，因事逃亡，后来学习符箓、祷祀等术。在十五世纪，礼仪、医药、星占与宗教技术并非边缘娱乐，宫廷会把它们用于祈福、灾异和身体治理。问题不在“迷信者天生邪恶”，而在专业真假、利益关系与公共资源如何核查。现存早年材料几乎都出自其失势后的佞幸传，个人动机无法精确复原。", [S307, S304], ["v141_yongchang_temple"], ["m141_liangfang"]),
            sec("v141_lizisheng_s2", "梁芳引入与密奏权", "经梁芳等人引介，李孜省获得秘密奏事渠道。密奏可保护举报者、让皇帝绕过迟缓官署，也使被指控者难以知道证据并答辩。他从祷祀逐渐介入官员升降，显示信息渠道一旦与奖惩相连，就会吸引求官者和中介。不能把每封密奏都预设为虚假，更应追问案件是否转交有职官署复核。", [S307, S304], ["v141_chuanfeng_network"], ["jianshen", "m141_liangfang"]),
            sec("v141_lizisheng_s3", "传奉不是一张同质名单", "史载李孜省周围的文武、僧道和方术者借传奉授官，名额累积甚多。有人确属投机，也可能有人具备技艺；制度缺陷在于没有公开考试、资历、缺额和回避程序。1485年清查后大量复任，说明问题不是一次抓出坏人就能结束。五百余、六十七等数字来自官府清册，只能说明规模和反复，不能替每个人作能力判决。", [S307, S168], ["v141_1485_review"], ["m141_liangfang", "m141_wanan"]),
            sec("v141_lizisheng_s4", "寺院、封号与物质成本", "李孜省的网络还连接继晓等僧人、封号和寺院营建。大永昌寺据史传涉及拆迁住户和巨额支出，应把失居家庭、工匠与运输者写回故事；同时，不能把利用宫廷关系的少数近幸扩大为对佛教、道教及普通僧侣的总体判断。真正需要核查的是土地来源、补偿、财物和授号程序。", [S307, S304], ["v141_yongchang_temple"], ["m141_liangfang", "jianshen"]),
            sec("v141_lizisheng_s5", "弘治追责与证据边界", "1487年政权更替后，李孜省被流放、召回审讯，最终在狱中死亡。官修传记据追责案卷叙述其罪，材料可能包含刑讯供词；即使其操弄密奏与人事可以由多条记录互证，酷刑和未经充分程序的死亡也不能被新政目标正当化。弘治清理恢复了部分常规入口，但宫廷密旨并未从明代政治消失。", [S307, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian", "m141_liangfang"]),
        ]),
        article("m141_liangfang", "梁芳：宫廷消费背后的采办网络", "珠宝、寺院与官职不是三件孤立的事；它们通过进献、近侍和密旨共同消耗财政并改变地方生活。", [
            sec("v141_liangfang_s1", "从采办珍玩获得信任", "梁芳以珠宝奇巧迎合宫廷，逐步接近成化帝与万贵妃。宫廷消费并不止于内库付款：采购者、商人、州县、工匠和运输者可能分别承担垫款与差役。列传聚焦他的贪黩，无法给出每件物品的完整账簿，但足以提示私人进献与公共财政边界模糊。皇帝的持续需求是网络扩展的前提。", [S304, S307], ["v141_palace_procurement"], ["jianshen", "m141_lizisheng"]),
            sec("v141_liangfang_s2", "采办名义怎样向地方传导", "梁芳同党借烧造、购买和进献到地方索取财物。中央的一句喜好，经过承办官、商人和基层胥吏，可能变成加价、派料和运输负担。现存史料擅长记录奢侈和奸人，却少有普通家庭账目，不能虚构全国统一摊派；阅读时应明确这一证据缺口，同时解释为何宫廷消费不能只按成品价格计算。", [S304, S307], ["v141_palace_procurement"], ["jianshen"]),
            sec("v141_liangfang_s3", "把李孜省带入宫廷", "梁芳引介李孜省等方术者，使采办信任进一步转化为密奏和人事资源。求官者可以绕过吏部，通过近侍、仪式和进献获得传奉。梁芳不是唯一操纵者：皇帝批准、外朝填写告身、有关官署发放俸禄，才使口头渠道成为长期制度负担。把全部责任压给宦官，会让授权者和合作者从叙事中消失。", [S304, S307], ["v141_chuanfeng_network"], ["m141_lizisheng", "m141_wanan", "jianshen"]),
            sec("v141_liangfang_s4", "继承传闻必须标明层次", "《明史》记梁芳等曾迎合改变太子的意图，怀恩加以阻止。此事涉及宫禁密议，主要来自后来的忠奸传记，不能写成有完整会议记录的确定方案。可以确认的是朱祐樘在成化后期处境敏感，宫廷关系会影响继承安全；更严谨的写法，是区分可核实的人事行动、后世转述和无法证明的心理。", [S304, S15], ["v141_hongzhi_accession_cleanup"], ["jianshen"]),
            sec("v141_liangfang_s5", "失势不能替代制度复盘", "弘治即位后，梁芳先被谪居，后入狱，相关传奉官与封号被清理。惩处个人释放了新政信号，却不能追回所有地方成本，也没有自动建立内库公开账目。评价梁芳既要保留其主动联结采办、方术和任命的责任，也要看到网络为何能运转十余年；只有任命、采购和土地程序同时改变，清理才不只是换一批近侍。", [S304, S15], ["v141_hongzhi_accession_cleanup"], ["m141_lizisheng", "m40_liujian"]),
        ]),
        article("m42_qiujun", "丘濬：把国家治理写成一套可讨论的目录", "《大学衍义补》的价值不在提供万能答案，而在把分散的财政、礼制、用人与边防问题放到同一政策框架。", [
            sec("v141_qiujun_s1", "从琼山借书少年到翰林官", "丘濬幼年失父，家贫而远行借书，景泰五年中进士后进入翰林。列传的勤学故事带有典型人物塑造，但他的长期编修、讲学和熟悉典章可以由官历确认。海南出身并未让他天然代表地方社会；相反，进入中央经典与档案体系后，他逐步学会用王朝制度语言处理疆域、财政和人事。", [S181, SDX], ["v141_daxue_yanyibu_event"], ["m40_lixian"]),
            sec("v141_qiujun_s2", "两广方略与知识的限度", "成化初两广用兵，丘濬向李贤陈述地势与方略，转给赵辅、韩雍参考。前线并未完全照办，说明书面知识必须接受地形、兵力和当地情势检验。后来战果不能全部归功于他的建议，战争中的焚毁和杀伤也不能被“谋略有效”遮蔽。这段经历使他获得名声，也揭示中枢知识需要前线修正。", [S181, "v42m_ms178"], ["v42m_datengxia"], ["m40_lixian", "m42_hanyong"]),
            sec("v141_qiujun_s3", "《大学衍义补》补了什么", "丘濬认为旧作重修身、齐家而治国条目不足，因而按财政、用人、礼制、司法、边防等门类广采前代材料。它把国家问题编成可以检索和比较的目录，也以内地农业、君主中心和儒家伦理组织世界。阅读时应同时看到知识汇总能力与时代边界，不能把规范性论述误作弘治社会的客观调查。", [S181, SDX], ["v141_daxue_yanyibu_event"], ["m40_liujian"]),
            sec("v141_qiujun_s4", "刊行、摘议与执行之间", "孝宗命刊行《大学衍义补》，丘濬入阁后又请求摘取要点交内阁讨论。印刷使文本进入更广的官僚学习网络，但皇帝称善、内阁议行都不等于每条落地。政策还要面对预算、既得利益、地方能力和不同官员判断。把“上书被采纳”拆成出版、讨论、诏令与执行，才能避免将思想影响夸大为直接治理成效。", [S181, S15, SDX], ["v141_daxue_yanyibu_event"], ["m40_liujian", "m40_xieqian"]),
            sec("v141_qiujun_s5", "学问、刚直与政治冲突", "丘濬上二十二事批评私谒、偏听与耗财，同时性格激烈，与刘健、王恕在人事考核上严重冲突。他曾主张为于谦平反，显示判断不能用党派标签概括；在官员去留上又可能过度坚持己见。学术系统性没有消除权力关系，廉洁也不保证每项判断正确。将争论双方意见并列，比单称贤相或褊臣更接近真实政治。", [S181, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian", "yuqian"]),
        ]),
        article("m40_liujian", "刘健：弘治议政中的节用、召对与边防", "他的影响来自长期讲官经验、同僚合作与皇帝采纳；“弘治中兴”不能简化为一名首辅主持一切。", [
            sec("v141_liujian_s1", "东宫讲官建立的信任", "刘健由翰林官长期担任东宫讲官，朱祐樘即位后进入内阁。讲筵既传授经典，也让未来皇帝熟悉官员的判断方式；这种信任提供议政入口，却不是独立权力。弘治初清理传奉网络、恢复较常规任用时，旧讲官成为可依赖人选。把它称作个人知遇可以，但不能忽略翰林、詹事府和内阁的制度路径。", [S181, S15], ["v141_hongzhi_accession_cleanup"], ["m42_qiujun", "m40_xieqian", "m40_lidongyang"]),
            sec("v141_liujian_s2", "财政问题从宫廷日用累积", "1501年军饷告急，刘健等把光禄供应、织作、斋醮、内库取银、庄田、营造和冗官俸薪并列。这不是抽象倡俭，而是指出前线缺饷与宫廷支出使用同一有限财源。奏议中的倍数和金额是劝谏口径，需要财政档案互证；其核心仍清楚：若只向民间加征而不审查内部支出，军费会把不透明成本继续下压。", [S181, S15], ["v141_border_finance_1501"], ["m40_xieqian", "m40_lidongyang"]),
            sec("v141_liujian_s3", "庄田与织造需要区分诏令和执行", "弘治朝限制投献庄田、停止一批额外织造，体现刘健等节用方向。皇庄管事仍可能侵田扰民，停止额外织造也不等于取消正式岁额。中枢决策必须经过户部、地方官和内府执行，才能改变佃户、工匠的日常负担。因此评价改革不能只统计颁布多少诏令，还要追问土地归还、欠料结算和申诉是否可达。", [S181, S77, S15], ["v141_huangzhuang_agents", "v141_weaving_reduction"], ["m40_xieqian", "m40_lidongyang"]),
            sec("v141_liujian_s4", "召对扩大了信息带宽", "弘治十三年边警后，孝宗在平台召刘健、李东阳、谢迁面议京营将领，晚年又较多召见大臣。面对面问答能让不同意见迅速碰撞，却仍取决于皇帝愿意听取、记录和执行。三人协作常被概括为刘断、李谋、谢侃侃，这是后世评价而非固定分工。一次召对也不能证明宫廷与外朝之间从此没有信息阻隔。", [S181, S15], ["v141_border_finance_1501"], ["m40_xieqian", "m40_lidongyang"]),
            sec("v141_liujian_s5", "谨慎出兵与制度遗产", "小王子威胁大同时，刘健主张整顿京营、减少役作，后来与兵部反对仅凭近侍建议仓促出兵。谨慎并非消极避战，而是评估训练、粮饷和指挥链。孝宗临终托付后，他在武宗初年继续清弊，最终因反对刘瑾失败而去职。个人威望能延续政策一时，不能跨越君主更替保证同一治理方式。", [S181, S15], ["v141_border_finance_1501"], ["m40_xieqian", "m40_lidongyang"]),
        ]),
        article("m40_xieqian", "谢迁：先核查支出，再谈向地方加税", "他把财政争论拉回承担者：边饷确实紧张，但增税之前必须审查宫廷、禁军和仓场为何失控。", [
            sec("v141_xieqian_s1", "讲筵不是礼仪表演", "谢迁乡试、会试皆居前列，成化末担任东宫讲官。孝宗即位初，他反对在大丧未毕时急选妃嫔，后来日讲前整衣熟诵，力求把经典与现实政务相连。讲筵没有直接行政权，却为皇帝提供不同于近侍的稳定信息来源。其影响仍依赖君主采纳，不能把称善写成政策已经执行。", [S181, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian"]),
            sec("v141_xieqian_s2", "边饷不足不等于立即加税", "大同边警、军饷紧张时，有人建议提高南方两税折银。谢迁指出南方原以折银减轻运输和税负，再加会使民众难以承担；应先节省无效支出。这个意见没有否认边防需求，而是要求解释谁先承担财政调整。最终增议被停，仍不能推定地方原有税役已经轻松。", [S181, S15], ["v141_border_finance_1501"], ["m40_liujian", "m40_lidongyang"]),
            sec("v141_xieqian_s3", "禁军空额不能只发一道禁令", "孝宗晚年，内库、仓场、马坊和禁军存在冒饷、空名等问题。谢迁认为笼统下令无效，应让主管部门逐项搜查，再建立可执行规则并追责。这个主张把“整顿”拆成证据、规则和执行，避免用高压口号替代调查；但现有列传未保存完整清查结果，不能写成积弊已经根除。", [S181, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian", "m40_lidongyang"]),
            sec("v141_xieqian_s4", "内阁协作不是三人同声", "谢迁与刘健、李东阳同在内阁，善于当面辨析，三人常共同进谏。协作提高了奏议连续性，也存在丘濬等不同意见，内阁并非思想一致的小团体。将“李谋、刘断、谢侃侃”当作形象提示可以，不能替代每一议题的证据。真正重要的是意见能否进入召对、留下案卷，并由有关官署执行。", [S181, S15], ["v141_daxue_yanyibu_event"], ["m40_liujian", "m40_lidongyang", "m42_qiujun"]),
            sec("v141_xieqian_s5", "从弘治合作到正德辞职", "孝宗晚年，谢迁参与财政、边防和太子教育。武宗即位后，三阁臣试图依遗诏清理弊政，因刘瑾等近侍反扑而失败，谢迁与刘健辞职。制度若只依赖一位皇帝信任，继承后就容易中断。谢迁的去留显示拒绝署名可以保存政治责任，却不能独自阻止新权力网络形成。", [S181, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian", "m40_lidongyang"]),
        ]),
        article("m40_lidongyang", "李东阳：让地方见闻进入中枢文书", "他擅长文章，却不只装点朝廷；最有价值的奏疏之一，正来自离开京城后对灾荒与劳役的观察。", [
            sec("v141_lidongyang_s1", "早慧故事之外的长期训练", "李东阳幼年被景帝召见的故事很著名，可靠的政治能力更多来自翰林编修、实录与东宫讲官的长期训练。诏敕写作不是文辞装饰，它要准确界定命令对象、理由与执行范围。弘治朝奏章繁多，他入阁负责诰敕，后来参与机务。才名提供入口，能否把信息转成可执行文本才决定实际作用。", [S181, S15], ["v141_hongzhi_accession_cleanup"], ["m40_liujian", "m40_xieqian"]),
            sec("v141_lidongyang_s2", "用经典讨论当下政策", "弘治五年旱灾求言，李东阳摘取《孟子》条目并联系时政得失上奏。以经典为共同语言，能让批评进入君臣都承认的框架，也可能让具体利益关系被道德词汇遮蔽。判断奏议质量不能只看引经多少，还要看是否指出责任、成本与执行机构。皇帝称善是讨论起点，不是改革结果。", [S181, S15], ["v141_daxue_yanyibu_event"], ["m42_qiujun"]),
            sec("v141_lidongyang_s3", "出使途中看见文书之外", "1504年赴曲阜途中，李东阳亲见旱田、挽舟者和农民饥色，又听到江南流亡、军伍空虚、欠俸与库存不足。他承认若不经过当地，即使每天处理奏章也难知详情。这份见闻不是完整调查，却揭示地方官可能隐瞒、庙堂摘要失真、宫廷再度过滤的多层信息损失。", [S181, S15], ["v141_lidongyang_drought_journey"], ["m40_liujian", "m40_xieqian"]),
            sec("v141_lidongyang_s4", "织造、商税和权势土地相互连接", "李东阳将灾荒与冗食、差役、土木、势家占田、王府供应、皇亲仆从包揽商税、织造内官扰民并列。它说明经济压力不是单一天灾，而是多个特权入口同时抽取资源。奏疏仍有劝谏修辞，不能把沿途所闻推广为每个地区同等严重；但将自然灾害与制度负担合读，是理解流亡的重要进步。", [S181, S77], ["v141_huangzhuang_agents", "v141_lidongyang_drought_journey"], ["m40_liujian", "m40_xieqian"]),
            sec("v141_lidongyang_s5", "留任的贡献与争议", "弘治末李东阳与刘健、谢迁共同受顾命。武宗初反刘瑾失败后，刘、谢辞职，李东阳留下，后来以在位斡旋减少部分迫害，也因此承受依附权势的批评。留任和辞职都可能有公共理由，也都受个人处境约束。评价应逐项核对他签署、阻止和妥协了什么，不能用一个选择覆盖此前的地方观察和财政奏议。", [S181, S15], ["v141_border_finance_1501"], ["m40_liujian", "m40_xieqian"]),
        ]),
    ]
    additions = {
        "v141_wanan_s1": "成化朝的决策迟缓也不能全部归因于一人：皇帝是否召见、司礼监如何递送、各部是否坚持复核，共同决定一份票拟的实际方向。万安的个案因此适合用来观察内阁权力的上限：能够塑造议程和措辞，却无法在皇帝反对时独自维持一项规则。",
        "v141_wanan_s2": "因此，研究宫廷关系不能停在亲属传闻，还应比较哪些任命绕过吏部、哪些批评被留中，以及利益最终由谁获得。",
        "v141_wanan_s3": "同一名阁臣既能在厂卫问题上联署反对，又能容忍别的非正式渠道，恰好说明制度边界必须逐项建立，不能依赖品格一致。",
        "v141_wanan_s4": "若名册被裁后仍可凭另一道口谕恢复，负责发俸、授衔和考核的官署就会同时面对两套权威，清查自然难以持续。",
        "v141_wanan_s5": "新君借更换首辅表达方向很有效，却仍需把召对、人事审查和财政记录变成日常程序，才能不再依赖下一位皇帝的好恶。",
        "v141_lizisheng_s1": "方术知识的社会位置也在变化：它既可能服务疾病与仪式需求，也可能被包装为只有近幸才能验证的能力，后者尤其容易逃避公开检验。李孜省并不是凭方术自动掌权；决定性变化是技术声望与秘密奏事、官职奖惩接合，知识争议才转化为制度风险。",
        "v141_lizisheng_s2": "密奏最危险的环节不是保密本身，而是保密从线索保护延伸到任命和定罪终局，使提出异议者只能挑战皇帝已经形成的判断。",
        "v141_lizisheng_s3": "授官还会产生长期俸禄、衙署职位和晋升预期；一次非正式任命的成本并不在颁旨当日结束，而会进入未来财政和组织结构。",
        "v141_lizisheng_s4": "寺院也可能承担礼拜、施舍和社区联系，不能因一项宫廷工程的越界就抹去这些功能；批评应精确指向取得资源的程序。",
        "v141_lizisheng_s5": "追责材料能帮助重建网络，却必须与本纪、相关人物传和任命记录互证；越是包含供词与刑罚，越不能只读成胜利者公布的事实清单。",
        "v141_liangfang_s1": "珍玩进入宫廷后常只留下赏赐和品名，生产端的人名与报酬更易消失；这种档案不对称本身就是理解奢侈政治的一部分。珠宝的稀缺性还会放大中间人的议价能力，使“知道哪里有货”变成接近宫廷的资本，随后再兑换为人事与工程请求。这个交换过程尤其值得核查。",
        "v141_liangfang_s2": "地方官若担心延误获罪，便可能先行垫办再向下追偿；即使中央没有写明加派，压力仍会在供应链中转移。",
        "v141_liangfang_s3": "吏部与有关衙门若拒绝执行，可能承担违旨风险；若一概执行，则常规任官名义尚在、实质审查却被架空，这正是两套通道并存的困境。",
        "v141_liangfang_s4": "继承史尤其容易被后来结局重新组织：太子最终即位，会让所有危险传闻显得早有预谋。材料没有回答的部分必须继续留白。",
        "v141_liangfang_s5": "宫廷消费还应留下项目、数量、付款与退补记录，官职则应回到缺额和资格审查；否则个人倒台后，同样机制仍可由新人接手。",
        "v141_qiujun_s1": "他的阅读范围来自个人勤奋，也依赖帝国征集、编纂和藏书体系；所谓博学背后，同样有抄写者、书坊和地方送书者的劳动。由边远海岛进入中央并不表示障碍消失，反而使交通、家境和教育资源的稀缺更值得注意；个人成功不能证明机会已经普遍开放。",
        "v141_qiujun_s2": "两广并非单一地理单元，当地族群、交通和寨堡关系远比中枢图册复杂；前线调整方案，不能简单解释为没有采用正确计策。",
        "v141_qiujun_s3": "全书大量引用前代制度，提供比较视野，也容易把历史经验抽离原有社会条件。读者需要分清引文、作者判断和当朝建议三种层次。",
        "v141_qiujun_s4": "刊本还能进入学校、官员书房和后来的制度讨论，其影响往往是长期改变问题分类，而不一定对应一条可追踪的即时诏令。",
        "v141_qiujun_s5": "他要求宽大，却也会在争论中激烈排斥对方，这种张力提醒我们：写下的政治原则与身处权力关系时的实践并不天然一致。",
        "v141_liujian_s1": "讲官与太子的接触受礼仪和课程约束，并非私人友谊；正因如此，这种信任较易被官僚体系承认，也较容易形成持续的政策对话。讲筵仍偏重经史与君德，地方财政和军情需要六部、言官及出使者补充；它是信息结构的一层，而不是包办全部治理知识。",
        "v141_liujian_s2": "奏疏把看似分散的费用放在一张财政图上，使节用不再只是个人美德，而成为军队能否按时领饷、地方能否免于加派的问题。",
        "v141_liujian_s3": "庄田涉及土地权属，织造涉及物料和劳动，两者不能用同一种裁撤办法。前者需勘界与归还，后者需核定岁额、工价和欠款。",
        "v141_liujian_s4": "召对若没有后续题本和部议，也可能只留下皇帝称善的政治表态；把口头同意追踪到执行，是判断内阁影响的必要步骤。",
        "v141_liujian_s5": "边防意见还需与马文升、刘大夏等兵部官员合读，才能看见内阁、兵部、京营和监军各自掌握的信息，而不是只突出首辅。",
        "v141_xieqian_s1": "他在服丧期间辞让入阁，也显示官僚伦理会直接影响任职时间。礼制不只是象征，它安排谁在何时能够进入决策位置。谢迁的科举名次常被传记突出，但名次只能解释仕途起点；随后二十年的讲读、文书和议政经验，才使他能够判断税赋与禁军问题。其判断也需要户部账册、兵部名籍和地方奏报支持，不能由道德声望代替技术核查。",
        "v141_xieqian_s2": "折银本来可能减少实物运输成本，却也受银价和地区市场影响。是否加额不能只看账面数目，还要估计纳税者取得白银的实际代价，以及灾年变卖粮物时承受的折损。",
        "v141_xieqian_s3": "搜剔空额也会触动依赖军饷生活的家庭，因此核查必须区分不存在的名额、代领舞弊与真实服役但登记混乱，避免整顿再伤及基层。",
        "v141_xieqian_s4": "内阁之外还有六部、都察院和给事中，许多信息与反对意见来自这些官署。三位阁臣的重要性不能覆盖更广泛的官僚协商。",
        "v141_xieqian_s5": "正德初年的逆转也反向说明弘治成果的限制：依靠君臣默契推进的整顿，如果没有稳定程序，就可能随宫廷人员更换迅速失效。",
        "v141_lidongyang_s1": "诏稿会在全国抄传，措辞若含糊，地方执行就可能扩大或缩小范围。文章能力因此既是文化声望，也是行政责任。诏敕也会选择哪些原因公开、哪些宫廷争论隐去，执笔者并非中性的抄写员；研究时应把正式文本与此前奏议、后来执行并读，并注意文本在层层抄写中的变化。",
        "v141_lidongyang_s2": "灾异奏议把旱情解释为政治警告，是当时常见表达。今天无需接受天人因果，仍可从中辨认官员借灾情要求开放言路的行动，以及地方救荒措施是否随后落实。",
        "v141_lidongyang_s3": "他沿运河和驿路所见，也偏向交通干线；远离路线的村落可能更加沉默。承认观察范围，反而让这份奏疏的证据价值更清楚。",
        "v141_lidongyang_s4": "这些压力互相放大：歉收降低家庭余粮，差役占用劳力，织造和商税提高交易成本，占田又削弱重新生产的土地基础。",
        "v141_lidongyang_s5": "他后来在刘瑾时期的每次妥协需要另作专题核查；这里保留争议，是为了避免用晚年评价倒推弘治年间所有奏议的真伪。",
    }
    for reading in articles:
        for section in reading["sections"]:
            section["text"] += additions[section["id"]]
    for reading in articles:
        upsert(data["articles"], reading, key="person")

    for item in [
        {"from": "m141_wanan", "to": "m141_lizisheng", "role": "对其密奏与传奉网络缺少持续制约的首辅", "inverse": "其近幸网络在该首辅任内扩展", "period": "1470年代—1487", "note": "不是所有传奉均由万安直接安排，关联用于说明票拟与密旨并存。", "sources": [S168, S307]},
        {"from": "m141_liangfang", "to": "m141_lizisheng", "role": "将其引入宫廷并连接采办与方术", "inverse": "借其近侍渠道取得密奏入口", "period": "成化后期", "note": "二人的合作仍以皇帝授权为运转前提。", "sources": [S304, S307]},
        {"from": "m40_liujian", "to": "m40_xieqian", "role": "共同处理弘治财政、边防并辅政", "inverse": "共同处理弘治财政、边防并辅政", "period": "1495—1506", "note": "共同署名不表示每项判断完全一致。", "sources": [S181, S15]},
        {"from": "m40_liujian", "to": "m40_lidongyang", "role": "共同召对并审议财政边防", "inverse": "负责大量奏疏草拟并参与召对", "period": "1495—1506", "note": "内阁影响依赖孝宗召见和最终采纳。", "sources": [S181, S15]},
        {"from": "m42_qiujun", "to": "m40_liujian", "role": "同朝议政并在人事考核上发生冲突", "inverse": "同朝议政并在人事考核上发生冲突", "period": "1491—1495", "note": "争论说明弘治内阁不是无分歧的贤臣共同体。", "sources": [S181, S15]},
    ]:
        association(data, item)

    data["version"] = 115
    data["reviewed"] = "2026-10-31"
    DATA.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    narration = json.loads(NARRATION.read_text(encoding="utf-8"))
    changed = {reading["person"] for reading in articles}
    narration["entries"] = [entry for entry in narration["entries"] if entry["articleID"] not in changed]
    NARRATION.write_text(json.dumps(narration, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
